import React, { useEffect, useMemo, useState } from 'react';
import { api } from './api';
import { Calendar, dateFnsLocalizer } from 'react-big-calendar';
import { format, parse, startOfWeek, getDay } from 'date-fns';
import { enUS } from 'date-fns/locale';
import 'react-big-calendar/lib/css/react-big-calendar.css';

const emptyForms = {
  letter: { title: '', content: '', status: 'Draft' },
  lecture: { title: '', course: '', date: '', time: '', venue: '' },
  meeting: { title: '', with_whom: '', date: '', time: '', location: '' },
  commitment: { title: '', description: '', due_date: '', status: 'Pending' },
  talk: { title: '', topic: '', audience: '', due_date: '', priority: 'Medium', status: 'To Do' },
  reminder: { title: '', description: '', remind_at: '', recurrence: 'None', email: '' },
};

const EVENT_COLORS = {
  lecture: '#1a4f8a',
  meeting: '#2475b0',
  commitment: '#6c3483',
  talk: '#1a7a48',
};

const FILTER_LABELS = {
  lecture: 'Lectures',
  meeting: 'Meetings',
  commitment: 'Commitments',
  talk: 'Talks',
};

const locales = { 'en-US': enUS };

const localizer = dateFnsLocalizer({ format, parse, startOfWeek, getDay, locales });

function App() {
  const [data, setData] = useState({
    letters: [],
    lectures: [],
    meetings: [],
    commitments: [],
    talks: [],
    reminders: [],
  });
  const [forms, setForms] = useState(emptyForms);
  const [loading, setLoading] = useState(true);
  const [calendarView, setCalendarView] = useState('month');
  const [filters, setFilters] = useState({ lecture: true, meeting: true, commitment: true, talk: true });

  const loadAll = async () => {
    setLoading(true);
    try {
      const [letters, lectures, meetings, commitments, talks, reminders] = await Promise.all([
        api.get('/letters'),
        api.get('/lectures'),
        api.get('/meetings'),
        api.get('/commitments'),
        api.get('/talks'),
        api.get('/reminders'),
      ]);
      setData({
        letters: letters.data,
        lectures: lectures.data,
        meetings: meetings.data,
        commitments: commitments.data,
        talks: talks.data,
        reminders: reminders.data,
      });
    } catch (error) {
      console.error('Failed to load data', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadAll();
  }, []);

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      data.reminders
        .filter((r) => !r.is_sent && new Date(r.remind_at) <= now)
        .forEach((reminder) => {
          if (window.Notification && Notification.permission === 'granted') {
            new Notification(`Reminder: ${reminder.title}`, {
              body: reminder.description || 'Scheduled academic reminder is due now.',
            });
          }
          api
            .put(`/reminders/${reminder.id}`, { ...reminder, is_sent: 1 })
            .then(() => loadAll())
            .catch((err) => console.error('Failed to mark reminder as sent', err));
        });
    }, 30000);
    return () => clearInterval(timer);
  }, [data.reminders]);

  useEffect(() => {
    if (window.Notification && Notification.permission === 'default') {
      Notification.requestPermission().catch(() => null);
    }
  }, []);

  const onInput = (section, field, value) => {
    setForms((prev) => ({ ...prev, [section]: { ...prev[section], [field]: value } }));
  };

  const addRecord = async (section, endpoint) => {
    try {
      await api.post(endpoint, forms[section]);
      setForms((prev) => ({ ...prev, [section]: emptyForms[section] }));
      loadAll();
    } catch (error) {
      console.error(`Failed to add ${section}`, error);
    }
  };

  const deleteRecord = async (endpoint, id) => {
    try {
      await api.delete(`${endpoint}/${id}`);
      loadAll();
    } catch (error) {
      console.error('Failed to delete record', error);
    }
  };

  const calendarEvents = useMemo(() => {
    const lectureEvents = filters.lecture
      ? data.lectures
          .filter((item) => item.date && item.time)
          .map((item) => {
            const start = new Date(`${item.date}T${item.time}`);
            const end = new Date(start.getTime() + (item.duration || 60) * 60000);
            return { id: `lecture-${item.id}`, title: item.title, start, end, allDay: false, type: 'lecture' };
          })
      : [];

    const meetingEvents = filters.meeting
      ? data.meetings
          .filter((item) => item.date && item.time)
          .map((item) => {
            const start = new Date(`${item.date}T${item.time}`);
            const end = new Date(start.getTime() + 60 * 60000);
            return { id: `meeting-${item.id}`, title: item.title, start, end, allDay: false, type: 'meeting' };
          })
      : [];

    const commitmentEvents = filters.commitment
      ? data.commitments
          .filter((item) => item.due_date)
          .map((item) => ({
            id: `commitment-${item.id}`,
            title: item.title,
            start: new Date(`${item.due_date}T09:00:00`),
            end: new Date(`${item.due_date}T10:00:00`),
            allDay: false,
            type: 'commitment',
          }))
      : [];

    const talkEvents = filters.talk
      ? data.talks
          .filter((item) => item.due_date)
          .map((item) => ({
            id: `talk-${item.id}`,
            title: `${item.title} [${item.priority}]`,
            start: new Date(`${item.due_date}T11:00:00`),
            end: new Date(`${item.due_date}T12:00:00`),
            allDay: false,
            type: 'talk',
          }))
      : [];

    return [...lectureEvents, ...meetingEvents, ...commitmentEvents, ...talkEvents];
  }, [data.lectures, data.meetings, data.commitments, data.talks, filters]);

  const upcomingReminders = useMemo(() => {
    const now = new Date();
    return data.reminders
      .filter((item) => !item.is_sent && new Date(item.remind_at) >= now)
      .sort((a, b) => new Date(a.remind_at) - new Date(b.remind_at));
  }, [data.reminders]);

  const markReminderDone = async (reminder) => {
    try {
      await api.put(`/reminders/${reminder.id}`, { ...reminder, is_sent: 1 });
      loadAll();
    } catch (error) {
      console.error('Failed to mark reminder done', error);
    }
  };

  const recurrenceBadge = (r) => r && r !== 'None' ? ` \u21BB ${r}` : '';

  return (
    <div className="page">
      <header className="hero">
        <div className="hero-brand">
          <svg className="logo-svg" viewBox="0 0 36 36" width="44" height="44">
            <rect width="36" height="36" rx="10" fill="rgba(255,255,255,0.15)" stroke="rgba(255,255,255,0.35)" strokeWidth="1.5"/>
            <polyline points="9,25 18,11 27,25" fill="none" stroke="#fff" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"/>
            <line x1="14" y1="20" x2="22" y2="20" stroke="#fff" strokeWidth="2.2" strokeLinecap="round"/>
          </svg>
          <h1>NextUp</h1>
        </div>
        <p className="hero-sub">Academic Activity Tracker</p>
      </header>

      {loading && <p className="loading">Loading records...</p>}

      <main className="dashboard">
        <section className="panel">
          <h2>Letters and Approvals</h2>
          <div className="form-row">
            <input placeholder="Letter title" value={forms.letter.title} onChange={(e) => onInput('letter', 'title', e.target.value)} />
            <select value={forms.letter.status} onChange={(e) => onInput('letter', 'status', e.target.value)}>
              <option>Draft</option>
              <option>Sent</option>
              <option>Approved</option>
              <option>Rejected</option>
            </select>
          </div>
          <textarea placeholder="Letter content" value={forms.letter.content} onChange={(e) => onInput('letter', 'content', e.target.value)} />
          <button onClick={() => addRecord('letter', '/letters')}>Save Letter</button>
          <ul>{data.letters.map((item) => <li key={item.id}>{item.title} <span className={`status-badge status-${item.status.toLowerCase().replace(' ','-')}`}>{item.status}</span> <button className="mini" onClick={() => deleteRecord('/letters', item.id)}>Delete</button></li>)}</ul>
        </section>

        <section className="panel">
          <h2>Lecture Schedule</h2>
          <div className="form-row">
            <input placeholder="Lecture title" value={forms.lecture.title} onChange={(e) => onInput('lecture', 'title', e.target.value)} />
            <input placeholder="Course" value={forms.lecture.course} onChange={(e) => onInput('lecture', 'course', e.target.value)} />
          </div>
          <div className="form-row">
            <input type="date" value={forms.lecture.date} onChange={(e) => onInput('lecture', 'date', e.target.value)} />
            <input type="time" value={forms.lecture.time} onChange={(e) => onInput('lecture', 'time', e.target.value)} />
            <input placeholder="Venue" value={forms.lecture.venue} onChange={(e) => onInput('lecture', 'venue', e.target.value)} />
          </div>
          <button onClick={() => addRecord('lecture', '/lectures')}>Add Lecture</button>
          <ul>{data.lectures.map((item) => <li key={item.id}><span className="ev-dot" style={{background: EVENT_COLORS.lecture}}/> {item.date} {item.time} &mdash; {item.title} <em>({item.course})</em> <button className="mini" onClick={() => deleteRecord('/lectures', item.id)}>Delete</button></li>)}</ul>
        </section>

        <section className="panel">
          <h2>Meeting Schedule</h2>
          <div className="form-row">
            <input placeholder="Meeting title" value={forms.meeting.title} onChange={(e) => onInput('meeting', 'title', e.target.value)} />
            <input placeholder="With whom" value={forms.meeting.with_whom} onChange={(e) => onInput('meeting', 'with_whom', e.target.value)} />
          </div>
          <div className="form-row">
            <input type="date" value={forms.meeting.date} onChange={(e) => onInput('meeting', 'date', e.target.value)} />
            <input type="time" value={forms.meeting.time} onChange={(e) => onInput('meeting', 'time', e.target.value)} />
            <input placeholder="Location" value={forms.meeting.location} onChange={(e) => onInput('meeting', 'location', e.target.value)} />
          </div>
          <button onClick={() => addRecord('meeting', '/meetings')}>Add Meeting</button>
          <ul>{data.meetings.map((item) => <li key={item.id}><span className="ev-dot" style={{background: EVENT_COLORS.meeting}}/> {item.date} {item.time} &mdash; {item.title} with {item.with_whom} <button className="mini" onClick={() => deleteRecord('/meetings', item.id)}>Delete</button></li>)}</ul>
        </section>

        <section className="panel">
          <h2>Commitments Tracker</h2>
          <div className="form-row">
            <input placeholder="Commitment title" value={forms.commitment.title} onChange={(e) => onInput('commitment', 'title', e.target.value)} />
            <select value={forms.commitment.status} onChange={(e) => onInput('commitment', 'status', e.target.value)}>
              <option>Pending</option>
              <option>In Progress</option>
              <option>Completed</option>
            </select>
          </div>
          <div className="form-row">
            <input type="date" value={forms.commitment.due_date} onChange={(e) => onInput('commitment', 'due_date', e.target.value)} />
            <input placeholder="Description" value={forms.commitment.description} onChange={(e) => onInput('commitment', 'description', e.target.value)} />
          </div>
          <button onClick={() => addRecord('commitment', '/commitments')}>Add Commitment</button>
          <ul>{data.commitments.map((item) => <li key={item.id}><span className="ev-dot" style={{background: EVENT_COLORS.commitment}}/> {item.title} <span className={`status-badge status-${item.status.toLowerCase().replace(' ','-')}`}>{item.status}</span> {item.due_date && <em>due {item.due_date}</em>} <button className="mini" onClick={() => deleteRecord('/commitments', item.id)}>Delete</button></li>)}</ul>
        </section>

        <section className="panel full-width">
          <h2>Academic Calendar</h2>
          <div className="legend">
            {Object.entries(EVENT_COLORS).map(([type, color]) => (
              <span key={type} className="legend-item">
                <span className="legend-dot" style={{ background: color }} />
                {FILTER_LABELS[type]}
              </span>
            ))}
          </div>
          <div className="filter-bar">
            {Object.keys(filters).map((type) => (
              <button
                key={type}
                className={`filter-btn ${filters[type] ? 'filter-on' : 'filter-off'}`}
                style={filters[type] ? { background: EVENT_COLORS[type], borderColor: EVENT_COLORS[type] } : {}}
                onClick={() => setFilters((prev) => ({ ...prev, [type]: !prev[type] }))}
              >
                {filters[type] ? '\u2713 ' : ''}{FILTER_LABELS[type]}
              </button>
            ))}
          </div>
          <div className="calendar-shell">
            <Calendar
              localizer={localizer}
              events={calendarEvents}
              startAccessor="start"
              endAccessor="end"
              views={['month', 'week', 'day']}
              view={calendarView}
              onView={setCalendarView}
              style={{ height: 520 }}
              eventPropGetter={(event) => ({
                style: {
                  backgroundColor: EVENT_COLORS[event.type] || '#2d5da6',
                  border: 'none',
                  borderRadius: '5px',
                  color: '#fff',
                },
              })}
            />
          </div>
        </section>

        <section className="panel full-width">
          <h2>Reminders</h2>
          <div className="form-row">
            <input placeholder="Reminder title" value={forms.reminder.title} onChange={(e) => onInput('reminder', 'title', e.target.value)} />
            <input placeholder="Description" value={forms.reminder.description} onChange={(e) => onInput('reminder', 'description', e.target.value)} />
            <input type="datetime-local" value={forms.reminder.remind_at} onChange={(e) => onInput('reminder', 'remind_at', e.target.value)} />
          </div>
          <div className="form-row">
            <select value={forms.reminder.recurrence} onChange={(e) => onInput('reminder', 'recurrence', e.target.value)}>
              <option value="None">No Recurrence</option>
              <option value="Daily">Daily</option>
              <option value="Weekly">Weekly</option>
              <option value="Monthly">Monthly</option>
            </select>
            <input type="email" placeholder="Email for notification (optional)" value={forms.reminder.email} onChange={(e) => onInput('reminder', 'email', e.target.value)} />
          </div>
          <button onClick={() => addRecord('reminder', '/reminders')}>Create Reminder</button>
          <ul>
            {upcomingReminders.map((item) => (
              <li key={item.id} className="reminder-item">
                <span className="reminder-title">{item.title}</span>
                <span className="reminder-time">{new Date(item.remind_at).toLocaleString()}</span>
                {item.recurrence && item.recurrence !== 'None' && (
                  <span className="recurrence-badge">\u21BB {item.recurrence}</span>
                )}
                <button className="mini" onClick={() => markReminderDone(item)}>Done</button>
                <button className="mini" onClick={() => deleteRecord('/reminders', item.id)}>Delete</button>
              </li>
            ))}
          </ul>
        </section>

        <section className="panel full-width">
          <h2>Talks with Priority</h2>
          <div className="form-row">
            <input placeholder="Talk title" value={forms.talk.title} onChange={(e) => onInput('talk', 'title', e.target.value)} />
            <input placeholder="Topic" value={forms.talk.topic} onChange={(e) => onInput('talk', 'topic', e.target.value)} />
            <input placeholder="Audience" value={forms.talk.audience} onChange={(e) => onInput('talk', 'audience', e.target.value)} />
          </div>
          <div className="form-row">
            <input type="date" value={forms.talk.due_date} onChange={(e) => onInput('talk', 'due_date', e.target.value)} />
            <select value={forms.talk.priority} onChange={(e) => onInput('talk', 'priority', e.target.value)}>
              <option>High</option>
              <option>Medium</option>
              <option>Low</option>
            </select>
            <select value={forms.talk.status} onChange={(e) => onInput('talk', 'status', e.target.value)}>
              <option>To Do</option>
              <option>In Progress</option>
              <option>Done</option>
            </select>
          </div>
          <button onClick={() => addRecord('talk', '/talks')}>Add Talk</button>
          <ul className="priority-list">
            {data.talks.map((item) => (
              <li key={item.id} className={`priority-${item.priority.toLowerCase()}`}>
                <span className="ev-dot" style={{background: EVENT_COLORS.talk}}/>
                {item.title} &mdash; <strong>{item.priority}</strong> &mdash; {item.status}
                <button className="mini" onClick={() => deleteRecord('/talks', item.id)}>Delete</button>
              </li>
            ))}
          </ul>
        </section>
      </main>
    </div>
  );
}

export default App;
